NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'I Corinthians'

CHAPTERS = {
    1: {
        1: 'Pavel, poklican, da je po Božji volji apostol Jezusa Kristusa in naš brat Sostén,',
        2: 'Božji cerkvi, ki je v Korintu, tem, ki so posvečeni v Kristusu Jezusu, poklicani, da so sveti, z vsemi, ki na vsakem kraju, tako njihovem kakor našem, kličejo ime Jezusa Kristusa, našega Gospoda:',
        3: '›Milost bodi vam in mir od Boga, našega Očeta in od Gospoda Jezusa Kristusa.‹',
        4: 'Vedno se vam v prid zahvaljujem svojemu Bogu za Božjo milost, ki vam je dana po Jezusu Kristusu,',
        5: 'da ste v vsaki stvari obogateni po njem, v vsej izgovarjavi in v vsem spoznanju;',
        6: 'celó kakor je bilo Kristusovo pričevanje potrjeno v vas,',
        7: 'tako da vam, ki pričakujete prihod našega Gospoda Jezusa Kristusa, ne primanjkuje nobenega daru;',
        8: 'ki vas bo tudi do konca potrdil, da boste lahko brez krivde na dan našega Gospoda Jezusa Kristusa.',
        9: 'Bog je zvest, po katerem ste bili poklicani v družbo njegovega Sina Jezusa Kristusa, našega Gospoda.',
        10: 'Torej vas rotim, bratje, v imenu našega Gospoda Jezusa Kristusa, da vsi govorite isto stvar in da med vami ne bo nobenih nesoglasij; temveč da boste popolnoma združeni skupaj, v istem mišljenju in v isti sodbi.',
        11: 'Kajti razodeto mi je bilo o vas, moji bratje, po teh, ki so iz Hloine hiše, da so med vami prepiri.',
        12: 'Pravim torej to, da vsak izmed vas govori: »Jaz sem Pavlov, jaz Apolov, jaz Kefov, jaz pa Kristusov.«',
        13: 'Ali je Kristus razdeljen? Ali je bil Pavel križan za vas? Ali ste bili krščeni v Pavlovo ime?',
        14: 'Zahvaljujem se Bogu, da nisem krstil nobenega izmed vas razen Krispa in Gaja,',
        15: 'da ne bi kdorkoli lahko rekel, da sem krščeval v svojem lastnem imenu.',
        16: 'In krstil sem tudi Stefanájevo družino; razen tega ne vem, če sem krstil kogarkoli drugega.',
        17: 'Kajti Kristus me ni poslal krščevat, temveč oznanjat evangelij; ne z modrostjo besed, da ne bi bil Kristusov križ storjen brez učinka.',
        18: 'Kajti oznanjevanje križa je tem, ki propadajo, nespametnost; toda nam, ki smo rešeni, je Božja moč.',
        19: 'Kajti pisano je: ›Uničil bom modrost modrih in zavrgel bom razum razsodnih.‹',
        20: 'Kje je modri? Kje je pisar? Kje je razpravljavec tega sveta? Mar ni modrosti tega sveta Bog naredil za nespametnost?',
        21: 'Kajti potem, ko v Božji modrosti svet po modrosti ni spoznal Boga, je Bogu ugajalo, da po nespametnosti oznanjevanja reši te, ki verujejo.',
        22: '§ Kajti Judje zahtevajo znamenje in Grki iščejo modrost,',
        23: 'toda mi oznanjamo križanega Kristusa, Judom kamen spotike in Grkom nespametnost;',
        24: 'toda tem, ki so poklicani, tako Judom kakor Grkom, [je] Kristus Božja moč in Božja modrost.',
        25: 'Kajti Božja nespametnost je modrejša od ljudi in Božja slabost močnejša od ljudi.',
        26: 'Kajti vidite svoj klic, bratje, da ni poklicanih veliko modrih po mesu, ne veliko mogočnih, ne veliko plemenitih;',
        27: 'toda Bog je izbral nespametne stvari sveta, da zbega modre; in Bog je izbral slabotne stvari sveta, da zbega stvari, ki so mogočne;',
        28: 'in nizke stvari sveta in stvari, ki so prezirane, je Bog izbral, da, in stvari, ki niso, da zavrže stvari, ki so,',
        29: 'da se v njegovi prisotnosti ne bi poveličevalo nobeno meso.',
        30: 'Toda vi ste iz njega v Kristusu Jezusu, ki je za nas postal modrost od Boga in pravičnost in posvečenje in odkupitev;',
        31: 'da, kakor je pisano: ›Kdor se ponaša, naj se ponaša v Gospodu.‹',
    },
    2: {
        1: 'In jaz, bratje, ko sem prišel k vam, razglašajoč Božje pričevanje, nisem prišel z odličnostjo govora ali z modrostjo.',
        2: 'Kajti odločil sem ne vedeti med vami nobene stvari, razen Jezusa Kristusa in njega križanega.',
        3: 'In z vami sem bil v slabosti in v strahu ter v mnogem trepetanju.',
        4: 'In moj govor in moje oznanjevanje nista bila s prepričevalnimi besedami človeške modrosti, temveč v prikazu Duha in moči,',
        5: 'da vaša vera ne bi stala na človeški modrosti, temveč na Božji moči.',
        6: 'Vendar govorimo modrost med temi, ki so popolni; vendar ne modrosti tega sveta niti princev tega sveta, ki se izjalovi;',
        7: 'temveč govorimo Božjo modrost v skrivnosti, celó prikrito modrost, ki jo je Bog pred svetom odredil v našo slavo;',
        8: 'ki je nobeden izmed princev tega sveta ni spoznal. Kajti če bi jo spoznali, ne bi križali Gospoda slave.',
        9: 'Toda kakor je pisano: ›Oko ni videlo niti uho slišalo niti ni vstopilo v človekovo srce, stvari, ki jih je Bog pripravil za tiste, ki ga ljubijo.‹',
        10: 'Toda Bog nam jih je razodel po svojem Duhu, kajti Duh preiskuje vse stvari, da, globoke Božje stvari.',
        11: 'Kajti kateri človek ve stvari o človeku razen človekovega duha, ki je v njem? Točno tako Božje stvari ne pozna noben človek, razen Božjega Duha.',
        12: '§ Torej nismo prejeli duha sveta, temveč duha, ki je od Boga; da bi lahko spoznali stvari, ki so nam velikodušno dane od Boga.',
        13: 'O katerih stvareh tudi govorimo, ne z besedami, ki jih uči človeška modrost, temveč ki jih uči Sveti Duh; [in] duhovne stvari primerjamo z duhovnimi.',
        14: 'Toda naraven človek ne sprejema stvari od Božjega Duha, kajti te so mu nespametnost; niti jih ne more razpoznati, ker se spoznavajo duhovno.',
        15: 'Toda kdor je duhoven, presoja vse stvari, čeprav on sam ni sojen od nobenega človeka.',
        16: 'Kajti kdo je spoznal Gospodov um, da bi ga lahko poučil? Toda mi imamo Kristusov um.',
    },
    3: {
        1: 'In jaz, bratje, vam nisem mogel govoriti kot duhovnim, temveč kot mesenim, celó kot otročičem v Kristusu.',
        2: 'Hranil sem vas z mlekom in ne z jedjo, kajti doslej je niste bili zmožni prenesti niti še sedaj ne zmorete.',
        3: '§ Kajti še vedno ste meseni; kajti glede na to, da so med vami zavist in prepir in nesoglasja, mar niste meseni in živite kot ljudje?',
        4: 'Kajti dokler nekdo govori: »Jaz sem Pavlov,« drugi pa: »Jaz sem Apolov;« mar niste še meseni?',
        5: 'Kdo je potem Pavel in kdo je Apolo, če ne služabnika, po katerih verujete, prav kakor je Gospod dal vsakemu človeku?',
        6: 'Jaz sem zasadil, Apolo zalil, toda Bog je dal rast.',
        7: 'Torej potem ni nič, kdor sadi niti kdor zaliva, temveč Bog, ki daje rast.',
        8: 'Torej kdor sadi in kdor zaliva, sta eno; in vsak bo svojo lastno nagrado prejel glede na svoj lastni trud.',
        9: 'Kajti midva sva delavca skupaj z Bogom. Vi ste Božje poljedelstvo, vi ste Božja zgradba.',
        10: 'Glede na milost od Boga, ki mi je dana kot modremu stavbeniku, sem položil temelj in drug gradi na njem. Toda vsak naj pazi, kako gradi na njem.',
        11: 'Kajti drugega temelja, kot je položen, ki je Jezus Kristus, noben človek ne more položiti.',
        12: 'Torej če katerikoli človek na tem temelju gradi zlato, srebro, dragocene kamne, les, seno, strnišče;',
        13: 'delo vsakega bo razodeto, kajti razkril ga bo dan, ker bo razodet z ognjem; in ogenj bo preizkusil delo vsakega, kakšne vrste je.',
        14: 'Če delo kateregakoli človeka, ki je gradil na njem, ostane, bo prejel nagrado.',
        15: 'Če bo delo kateregakoli človeka zgorelo, bo trpel izgubo, toda on sam bo rešen; vendar tako kakor z ognjem.',
        16: 'Ali ne veste, da ste Božji tempelj in da Božji Duh prebiva v vas?',
        17: 'Če katerikoli človek omadežuje Božji tempelj, bo Bog uničil njega; kajti Božji tempelj je svét, čigar tempelj ste vi.',
        18: 'Naj se noben človek ne vara. Če se komurkoli med vami zdi, da je v tem svetu moder, naj postane bedak, da bo lahko moder.',
        19: 'Kajti modrost tega sveta je pri Bogu norost. Kajti pisano je: ›Modre zasači v njihovi lastni prebrisanosti.‹',
        20: 'In ponovno: ›Gospod pozna misli modrih, da so prazne.‹',
        21: 'Torej naj se noben človek ne ponaša z ljudmi. Kajti vse stvari so vaše:',
        22: 'bodisi Pavel ali Apolo ali Kefa ali svet ali življenje ali smrt ali sedanje stvari ali stvari, ki pridejo; vse so vaše;',
        23: 'vi ste Kristusovi, Kristus pa je Božji.',
    },
    4: {
        1: 'Naj človek tako misli o nas kakor o Kristusovih služabnikih in oskrbnikih Božjih skrivnosti.',
        2: 'Poleg tega je pri oskrbnikih zahtevano, da je človek najden zvest.',
        3: 'Toda kar se mene tiče je to zelo majhna stvar, da bi bil sojen od vas ali od človeške sodbe. Da, jaz samega sebe ne sodim.',
        4: 'Kajti sam od sebe ne vem nič, čeprav s tem nisem opravičen; toda kdor sodi mene, je Gospod.',
        5: 'Torej ničesar ne sodite pred časom, dokler ne pride Gospod, ki bo na svetlobo privedel tako skrite stvari teme, kakor bo razodel namene src; in tedaj bo vsak prejel pohvalo od Boga.',
        6: 'In te stvari, bratje, sem zaradi vas v podobi prenesel nase in na Apola, da bi se lahko na nama naučili ne misliti o ljudeh preko tega, kar je pisano, da se nobeden izmed vas ne bi napihoval drug proti drugemu.',
        7: 'Kajti kdo te dela, da se razlikuješ od drugega? In kaj imaš, česar nisi prejel? Torej, če si to prejel, zakaj se ponašaš, kakor če tega nisi prejel?',
        8: 'Sedaj ste siti, sedaj ste bogati, brez nas ste zakraljevali kakor kralji; in Bog daj, da ste zakraljevali, da bomo lahko tudi mi kraljevali z vami.',
        9: 'Kajti mislim, da je Bog nas apostole postavil zadnje, kakor bi bili določeni za smrt; kajti postali smo prizor svetu, angelom in ljudem.',
        10: 'Mi smo bedaki za Kristusa, toda vi ste modri v Kristusu; mi smo slabotni, toda vi ste močni; vi ste častitljivi, toda mi smo prezirani.',
        11: 'Celó do sedanje ure smo tako lačni kakor žejni, nagi, oklofutani in nimamo zanesljivega bivališča;',
        12: 'in trudimo se ter delamo s svojimi lastnimi rokami; ko smo zasramovani, blagoslavljamo; ko smo preganjani, to potrpimo;',
        13: 'ko smo psovani, milo prosimo. Postali smo kakor umazanija sveta in do današnjega dne smo izvržki vseh stvari.',
        14: 'Teh stvari vam ne pišem, da vas sramotim, temveč vas kot svoje ljubljene sinove svarim.',
        15: 'Kajti čeprav imate deset tisoč učiteljev v Kristusu, vendarle nimate mnogo očetov; kajti v Kristusu Jezusu sem vas po evangeliju rodil jaz.',
        16: 'Zatorej vas rotim, bodite moji posnemovalci.',
        17: 'Zaradi tega razloga sem k vam poslal Timóteja, ki je moj ljubljeni sin in zvest v Gospodu, ki vam bo priklical v spomin moje poti, ki so v Kristusu, kakor povsod v vsaki cerkvi učim.',
        18: 'Torej nekateri so napihnjeni, kot da ne bom prišel k vam.',
        19: 'Toda k vam bom prišel v kratkem, če Gospod hoče in ne bom spoznal govora teh, ki se napihujejo, temveč moč.',
        20: 'Kajti Božje kraljestvo ni v besedi, temveč v moči.',
        21: 'Kaj hočete? Naj pridem k vam s palico ali v ljubezni in v duhu krotkosti?',
    },
    5: {
        1: 'Pogosto se sporoča, da je med vami prešuštvo in to prešuštvo, kakršno je komaj imenovano med pogani, da naj bi nekdo imel ženo svojega očeta.',
        2: 'In vi ste napihnjeni in niste raje žalovali, da bi bil tisti, ki je to dejanje storil, lahko odvzet izmed vas.',
        3: 'Kajti resnično, čeprav telesno odsoten, toda prisoten v duhu, sem že sodil, kakor da sem bil prisoten, glede tistega, ki je storil to dejanje,',
        4: '§ v imenu našega Gospoda Jezusa Kristusa, ko ste z močjo našega Gospoda Jezusa Kristusa skupaj zbrani vi in moj duh,',
        5: 'da se takšnega izroči Satanu v uničenje mesa, da bi bil duh lahko rešen na dan Gospoda Jezusa.',
        6: 'Vaše ponašanje ni dobro. Mar ne veste, da malo kvasa prekvasi celotno gmoto?',
        7: '§ Počistite torej stari kvas, da boste lahko nova gmota, ker ste nekvašeni. Kajti celó Kristus, naše pashalno jagnje, je žrtvovan za nas.',
        8: 'Torej praznujmo praznik, ne s starim kvasom niti s kvasom hudobije in zlobnosti, temveč z nekvašenim kruhom iskrenosti in resnice.',
        9: 'V poslanici sem vam napisal, da se ne družite s prešuštvovalci,',
        10: 'čeprav ne skupaj s prešuštvovalci tega sveta ali z lakomniki ali izsiljevalci ali z malikovalci; kajti potem morate brezpogojno oditi s sveta.',
        11: 'Toda sedaj sem vam napisal, da se ne družite, če je katerikoli človek, ki se imenuje brat, prešuštvovalec ali lakomnik ali malikovalec ali obrekljivec ali pijanec ali izsiljevalec; s takšnim niti ne jejte.',
        12: 'Kajti kaj moram storiti, da sodim tudi tiste, ki so zunaj? Mar ne sodite vi tistih, ki so znotraj?',
        13: 'Toda tiste, ki so zunaj, sodi Bog. Torej to zlobno osebo odslovite izmed sebe.',
    },
    6: {
        1: 'Ali si drzne kdo izmed vas, ki ima zadevo zoper drugega, tožiti pred nepravičnimi, ne pa pred svetimi?',
        2: 'Mar ne veste, da bodo sveti sodili svet? In če bo svet sojen po vas ali ste nevredni, da sodite najmanjšim zadevam?',
        3: 'Mar ne veste, da bomo sodili angelom? Koliko bolj stvarem, ki se nanašajo na to življenje?',
        4: 'Če imate torej sodbe o stvareh, ki se nanašajo na to življenje, postavljate za sodnike tiste, ki so v cerkvi najmanj spoštovani.',
        5: 'Govorim v vašo sramoto. Ali je tako, da med vami ni modrega? Ni niti enega, ki bi bil sposoben razsoditi med svojimi brati?',
        6: 'Vendar se brat toži z bratom in to pred neverniki.',
        7: 'Torej je zato med vami skrajna krivica, ker se tožite drug z drugim. Zakaj raje ne sprejmete krivice? Zakaj raje ne dopustite, da ste ogoljufani?',
        8: 'Ne, vi delate krivico in goljufate, in to svoje brate.',
        9: 'Mar ne veste, da nepravični ne bodo podedovali Božjega kraljestva? Ne bodite zavedeni; niti prešuštvovalci, niti malikovalci, niti zakonolomci, niti poženščeni, niti tisti, ki sami sebe zlorabljajo z možmi,',
        10: 'niti tatovi, niti lakomniki, niti pijanci, niti zasramovalci, niti izsiljevalci ne bodo podedovali Božjega kraljestva.',
        11: '§ In takšni ste bili nekateri izmed vas; toda vi ste umiti, toda vi ste posvečeni, toda vi ste opravičeni v imenu Gospoda Jezusa in z Duhom našega Boga.',
        12: 'Dovoljene so mi vse stvari, toda vse stvari niso koristne. Dovoljene so mi vse stvari, toda podvržen ne bom pod oblast nobene.',
        13: 'Jedi [so] za trebuh in trebuh za jedi, toda Bog bo uničil tako to kakor te. Telo torej ni za prešuštvovanje, temveč za Gospoda; in Gospod za telo.',
        14: 'In Bog je obudil tako Gospoda, kakor bo po svoji lastni moči obudil tudi nas.',
        15: 'Mar ne veste, da so vaša telesa Kristusovi udje? Mar naj torej vzamem Kristusove ude in jih naredim za ude pocestnice? Bog ne daj.',
        16: 'Kaj? Mar ne veste, da kar je združeno s pocestnico, je eno telo? ›Kajti dva,‹ pravi on, ›bosta eno meso.‹',
        17: 'Toda kdor je pridružen h Gospodu, je en duh.',
        18: 'Bežite pred prešuštvom. Vsak greh, ki ga stori človek, je zunaj telesa; toda kdor zagreši prešuštvo, greši zoper svoje lastno telo.',
        19: 'Kaj? Mar ne veste, da je vaše telo tempelj Svetega Duha, ki je v vas, ki ga imate od Boga in niste sami svoji?',
        20: '§ Kajti odkupljeni ste s ceno; zato proslavite Boga v vašem telesu in v vašem duhu, ki sta Božja.',
    },
    7: {
        1: 'Torej glede stvari, o katerih ste mi pisali: ›Dobro je za moškega ne dotikati se ženske.‹',
        2: 'Kljub temu naj ima, v izogib prešuštvovanju, vsak mož svojo lastno ženo in vsaka ženska naj ima svojega lastnega soproga.',
        3: 'Naj soprog ženi vrača dolžno dobrohotnost in prav tako žena soprogu.',
        4: 'Žena nima oblasti nad svojim lastnim telesom, temveč soprog. In prav tako tudi soprog nima oblasti nad svojim lastnim telesom, temveč žena.',
        5: '§ Ne prikrajšujta se drug drugemu, razen če je to s soglasjem za nekaj časa, da se lahko predata postu in molitvi; in ponovno pridita skupaj, da vaju zaradi vajinega pomanjkanja samoobvladovanja ne skuša Satan.',
        6: 'Toda to govorim z dovoljenjem in ne po zapovedi.',
        7: 'Kajti želim, da bi bili vsi ljudje kakor jaz. Toda vsak človek ima svoj primeren dar od Boga, eden na ta način, drugi pa na drug.',
        8: 'Torej neporočenim in vdovam pravim: »Zanje je dobro, če ostanejo kakor jaz.«',
        9: 'Toda če se ne morejo brzdati, naj se poročé; kajti bolje se je poročiti kakor plameneti.',
        10: 'Poročenim pa naročam, čeprav ne jaz, temveč Gospod: »Naj žena ne odide od svojega soproga.',
        11: 'Toda če odide, naj ostane neomožena ali naj se pobota k svojemu soprogu, in soprog naj svoje žene ne odslovi.«',
        12: 'Toda drugim govorim jaz, ne Gospod: »Če ima katerikoli brat ženo, ki ne veruje in je zadovoljna, da prebiva z njim, naj je ne odslovi.',
        13: 'In ženska, ki ima soproga, ki ne veruje in če je zadovoljen, da prebiva z njo, naj ga ona ne zapusti.',
        14: 'Kajti neverni soprog je posvečen po ženi in neverna žena je posvečena po soprogu; sicer bi bili vaši otroci nečisti, toda sedaj so sveti.',
        15: 'Toda če neverni odide, naj odide. Brat ali sestra v teh primerih nista pod suženjstvom; toda Bog nas je poklical k miru.',
        16: 'Kajti kaj veš ti, oh žena, če boš rešila svojega soproga? Ali kako veš ti, oh mož, če boš rešil svojo ženo?«',
        17: 'Toda kakor je Bog vsakemu človeku razdelil, kakor je Gospod vsakogar poklical, tako naj hodi. In tako določam v vseh cerkvah.',
        18: 'Ali je poklican katerikoli mož, ki je obrezan? Naj ne postane neobrezan. Ali je kateri poklican neobrezan? Naj ne bo obrezan.',
        19: 'Obreza ni nič in neobreza ni nič, temveč izpolnjevanje Božjih zapovedi.',
        20: 'Naj vsak ostane v isti poklicanosti, v katero je bil poklican.',
        21: 'Ali si bil poklican kot služabnik? Ne skrbi za to. Toda če lahko postaneš svoboden, to vsekakor izkoristi.',
        22: 'Kajti kdor je poklican v Gospodu kot služabnik, je Gospodov osvobojenec; prav tako tudi kdor je poklican kot svoboden, je Kristusov služabnik.',
        23: 'Odkupljeni ste za ceno; ne bodite služabniki ljudem.',
        24: 'Bratje, naj vsak ostane z Bogom v tem, v čemer je bil poklican.',
        25: 'Torej glede devic nimam zapovedi od Gospoda; čeprav dam svoje mnenje kakor nekdo, ki je dosegel usmiljenje od Gospoda, da je zvest.',
        26: 'Domnevam torej, da je to dobro zaradi sedanje stiske; pravim, da je to dobro za človeka, da je tako.',
        27: 'Ali si vezan k ženi? Ne skušaj biti razvezan. Ali si razvezan od žene? Ne išči žene.',
        28: 'Toda če pa se poročiš, nisi grešil; in če se devica poroči, ni grešila. Vendar bodo taki imeli stisko v mesu; toda prizanašam vam.',
        29: 'Toda pravim to, bratje, čas je kratek. Preostaja to, da so tisti, ki imajo žene, kakor da jih ne bi imeli;',
        30: 'in tisti, ki jokajo, kakor ne bi jokali; in tisti, ki se veselijo, kakor da se ne bi veselili; in tisti, ki kupujejo, kakor ne bi imeli v lasti;',
        31: 'in tisti, ki uporabljajo ta svet, kakor ga ne bi zlorabljali; kajti videz tega sveta mineva.',
        32: 'Toda hočem, da ste brez skrbi. Kdor je neporočen, skrbi za stvari, ki pripadajo Gospodu, kako bi lahko ugajal Gospodu;',
        33: '§ toda kdor je poročen, skrbi za stvari, ki so od sveta, kako bi lahko ugajal svoji ženi.',
        34: '§ Razlika je tudi med ženo in devico. Neporočena ženska skrbi za Gospodove stvari, da bi bila lahko sveta, tako v telesu kakor v duhu; toda tista, ki je poročena, skrbi za svetne stvari, kako bi lahko ugodila svojemu soprogu.',
        35: 'In to govorim v vašo lastno korist; ne da bi na vas lahko vrgel zanko, temveč k temu kar je ljubko in da bi lahko nemoteno služili Gospodu.',
        36: '§ Toda če kateri človek misli, da se do svoje device vede nespodobno, če je minil cvet njenih let in potreba tako zahteva, naj stôri, kar hoče, ne greši; naj se poročita.',
        37: 'Vendar kdor v svojem srcu neomajno stoji in nima nujne potrebe, temveč ima oblast nad svojo lastno voljo in je v svojem srcu tako določil, da bo ohranil svojo devico, stori pravilno.',
        38: 'Tako torej kdor jo daje v zakon, stori pravilno; toda kdor je ne daje v zakon, stori bolje.',
        39: 'Žena je vezana s postavo, dokler njen soprog živi; toda če njen soprog umre, je prosta, da se poroči s komer hoče; le v Gospodu.',
        40: 'Toda po moji sodbi je srečnejša, če ostane tako; in mislim, da imam tudi jaz Božjega Duha.',
    },
    8: {
        1: 'Torej glede stvari, darovanih malikom, vemo, da imamo vsi spoznanje. Spoznanje napihuje, toda ljubezen izgrajuje.',
        2: 'In če katerikoli človek misli, da karkoli pozna, še nič ne pozna, kakor bi moral poznati.',
        3: 'Toda če katerikoli človek ljubi Boga, isti je spoznan od njega.',
        4: '§ Kar torej zadeva uživanje tistih stvari, ki so darovane v žrtvovanje malikom, vemo, da v svetu malik ni nič in da ne obstaja drug Bog razen enega.',
        5: 'Kajti čeprav obstajajo ti, ki se imenujejo bogovi, bodisi na nebu ali na zemlji (kakor obstaja mnogo bogov in mnogo gospodov),',
        6: 'toda za nas ni drugega razen enega Boga, Očeta, od katerega so vse stvari in mi v njem; in en Gospod Jezus Kristus, po katerem so vse stvari in mi po njem.',
        7: 'Vendar to spoznanje ne obstaja v vsakem človeku; kajti nekateri z vestjo malikov do te ure to jedo kot stvar, darovano maliku; in njihova slabotna vest je omadeževana.',
        8: 'Toda jed nas ne približa Bogu; kajti niti če jemo, nismo boljši; niti če ne jemo, nismo slabši.',
        9: 'Toda pazite, da ne bi na kakršenkoli način ta vaša svoboda postala kamen spotike tem, ki so slabotni.',
        10: 'Kajti če te katerikoli človek, ki ima spoznanje, vidi v templju malikov sedeti pri jedi, ali ne bo njegova vest, ki je slabotna, postala ohrabrena, da jé te stvari, ki so darovane malikom;',
        11: 'in zaradi tvojega spoznanja bo propadel slaboten brat, za katerega je Kristus umrl?',
        12: 'Toda kadar tako grešite proti bratom in prizadenete njihovo slabotno vest, grešite zoper Kristusa.',
        13: 'Zatorej, če jed stori, da se moj brat pohujša, dokler stoji svet ne bom jedel mesa, da ne bi svojega brata primoral grešiti.',
    },
    9: {
        1: 'Mar nisem apostol? Ali nisem svoboden? Mar nisem videl Jezusa Kristusa, našega Gospoda? Mar niste vi moje delo v Gospodu?',
        2: 'Če nisem apostol drugim, sem pa nedvomno vam; kajti vi ste pečat mojega apostolstva v Gospodu.',
        3: 'Moj odgovor tem, ki me zaslišujejo, je ta:',
        4: '›Ali nimamo pravice jesti in piti?',
        5: 'Ali nimamo pravice okrog voditi sestro, ženo, prav tako kakor drugi apostoli in kakor Gospodovi bratje ter Kefa?',
        6: 'Ali se samo jaz in Barnaba nimava pravice zadržati pred delom?',
        7: 'Kdo se kadarkoli gre vojskovanje na svoje lastne stroške? Kdo zasaja vinograd, pa ne jé od sadov le-tega? Ali kdo pase trop, pa ne jé mleka od tropa?',
        8: 'Ali govorim te besede kakor človek? Ali ne govori istega tudi postava?',
        9: 'Kajti v Mojzesovi postavi je pisano: ›Ne boš zavezal gobca volu, ki mane žito.‹ Ali Bog skrbi za vole?',
        10: 'Ali govori to predvsem zaradi nas? Zaradi nas, brez dvoma, tako je pisano; da naj bi tisti, ki orje, oral v upanju; in da bi bil tisti, ki mlati v upanju soudeleženec njegovega upanja.',
        11: 'Če smo vam sejali duhovne stvari, ali je velika stvar, če bomo želi vaše mesene stvari?',
        12: 'Če so drugi udeleženci te pravice nad vami, ali nismo tem bolj mi? Pa vendar te pravice nismo uporabili, temveč vse stvari prenašamo, da ne bi ovirali Kristusovega evangelija.',
        13: 'Ali ne veste, da tisti, ki služijo pri svetih stvareh, živijo od tempeljskih stvari? In da so tisti, ki prisostvujejo pri oltarju, udeleženci z oltarjem?',
        14: 'Točno tako je Gospod odredil, da naj tisti, ki oznanjajo evangelij, živijo od evangelija.',
        15: 'Toda sam nisem uporabil nobene od teh stvari niti nisem napisal teh stvari, da naj bi se mi tako zgodilo. Kajti zame bi bilo bolje, da umrem, kakor da bi katerikoli človek onemogočil moje ponašanje.',
        16: 'Kajti čeprav oznanjam evangelij, se nimam s čim ponašati, ker je name položena nuja; da, gorje meni, če ne oznanjam evangelija!',
        17: 'Kajti če to stvar počnem voljno, imam nagrado. Toda če proti svoji volji, mi je bilo zaupano razdeljevanje evangelija.',
        18: 'Kaj je potem moja nagrada? Resnično, da kadar oznanjam evangelij, smem narediti Kristusov evangelij brezplačen, da ne bi izkoriščal svoje pravice v evangeliju.',
        19: 'Kajti čeprav sem osvobojen vseh ljudi, sem vendar sebe naredil služabnika vsem, da bi jih lahko več pridobil.',
        20: 'In Judom sem postal kakor Jud, da bi lahko pridobil Jude; tem, ki so pod postavo, kakor pod postavo, da bi lahko pridobil te, ki so pod postavo;',
        21: 'tem, ki so brez postave, kakor brez postave (ne brez postave Bogu, temveč pod Kristusovo postavo), da bi lahko pridobil te, ki so brez postave.',
        22: 'Slabotnim sem postal kakor slaboten, da lahko pridobim slabotne. Storil sem vse stvari vsem ljudem, da bi jih vsekakor nekaj rešil.',
        23: 'In to počnem zaradi evangelija, da bom lahko z vami udeleženec le-tega.',
        24: 'Mar ne veste, da tisti, ki tečejo na tekmi, vsi tečejo, toda eden prejme nagrado? Tako tecite, da jo lahko dosežete.',
        25: 'Vsak pa, ki si prizadeva za nagrado, je zmeren v vseh stvareh. Torej oni to počno, da dosežejo ovenljiv venec; toda mi neovenljivega.',
        26: 'Zatorej tako tečem, ne kakor negotovo; tako se borim, ne kakor nekdo, ki tolče zrak;',
        27: 'temveč potlačim svoje telo in ga privedem v podložnost, da ne bi bil na kakršenkoli način, ko sem oznanjal drugim, sam bil zavržen.‹',
    },
    10: {
        1: 'Poleg tega bratje nočem, da vi ne bi premislili, da so bili vsi naši očetje pod oblakom in so vsi šli skozi morje',
        2: 'in vsi so bili krščeni v Mojzesa, v oblaku in v morju,',
        3: 'in vsi so jedli isto duhovno jed,',
        4: 'in vsi so pili isto duhovno pijačo. Kajti pili so iz te duhovne Skale, ki jih je spremljala. In ta Skala je bil Kristus.',
        5: 'Toda z mnogimi izmed njih Bog ni bil zelo zadovoljen; zato so bili zrušeni v divjini.',
        6: 'Torej te stvari so bile naši zgledi, z namenom, da mi ne bi hlepeli po zlih stvareh, prav tako kakor so oni poželeli.',
        7: 'Niti ne bodite malikovalci, kakor so bili nekateri izmed njih; kakor je pisano: ›Ljudje so se usedli, da bi jedli in pili in vstali, da bi se zabavali.‹',
        8: 'Niti ne zagrešimo prešuštvovanja, kakor so storili nekateri izmed njih in [jih] je v enem dnevu padlo triindvajset tisoč.',
        9: 'Niti ne skušajmo Kristusa, kakor so skušali tudi nekateri izmed njih in so bili pokončani od kač.',
        10: 'Niti ne godrnjajte, kakor so tudi nekateri izmed njih godrnjali in so bili pokončani od uničevalca.',
        11: 'Torej vse te stvari so se jim zgodile za zglede. Napisane pa so v svarilo nam, nad katere so prišli konci sveta.',
        12: 'Zato naj tisti, ki misli, da stoji, pazi, da ne pade.',
        13: 'Nobene preizkušnje niste prestali razen takšne, ki je človeku običajna. Toda Bog je zvest, ki ne bo dovolil, da bi bili skušani nad tem, kar ste zmožni; toda s preizkušnjo bo prav tako pripravil pot za pobeg, da jo boste lahko prestali.',
        14: 'Moji srčno ljubljeni, bežite torej od malikovanja.',
        15: 'Govorim kot modrim možem; presodite, kaj govorim.',
        16: 'Mar ni čaša blagoslova, ki jo blagoslavljamo, udeležba pri Kristusovi krvi? Mar ni kruh, ki ga lomimo, udeležba pri Kristusovem telesu?',
        17: 'Kajti mi, ki nas je mnogo, smo en kruh in eno telo; ker smo vsi udeleženci tega enega kruha.',
        18: 'Glejte Izrael po mesu. Mar niso tisti, ki jedo od žrtev, udeleženci oltarja?',
        19: 'Kaj torej pravim? Da je malik kaj, ali je to, kar je darovano v žrtvovanje malikom kaj?',
        20: 'Temveč pravim, da stvari, ki jih pogani žrtvujejo, žrtvujejo hudičem, ne pa Bogu; in ne želim, da bi vi imeli družbo s hudiči.',
        21: 'Ne morete piti Gospodove čaše in čaše hudičev. Ne morete biti udeleženci Gospodove mize in mize hudičev.',
        22: 'Ali Gospoda dražimo do ljubosumnosti? Ali smo močnejši od njega?',
        23: 'Dovoljene so mi vse stvari, toda vse stvari niso koristne. Dovoljene so mi vse stvari, toda vse stvari ne izgrajujejo.',
        24: 'Naj noben človek ne išče svojega lastnega, temveč vsak srečo drugega.',
        25: 'Karkoli se prodaja v mesnicah, to jejte, ne postavljajoč nobenih vprašanj glede vesti;',
        26: 'kajti Gospodova je zemlja in njena polnost.',
        27: 'Če vas kdorkoli od teh, ki ne veruje, povabi na pojedino in ste pripravljeni, da greste; jejte karkoli je postavljeno pred vas in ne sprašujte se nobenih vprašanj glede vesti.',
        28: '§ Toda če vam katerikoli človek reče: »To je darovano v žrtev malikom,« ne jejte zaradi tistega, ki je to pokazal in zaradi vesti; kajti zemlja je Gospodova in njena polnost.',
        29: 'Vesti pravim, ne tvoje lastne, temveč od drugega; kajti zakaj je moja svoboda sojena od vesti drugega človeka?',
        30: 'Kajti če sem udeleženec po milosti, zakaj sem obrekovan zaradi tega, za kar se zahvaljujem?',
        31: 'Če torej jeste ali pijete ali delate karkoli, vse to delajte v Božjo slavo.',
        32: 'Ne dajajte nobenega povoda, niti Judom, niti poganom, niti Božji cerkvi;',
        33: 'tako kakor jaz v vseh stvareh ugajam vsem ljudem in ne iščem svoje lastne koristi, temveč korist mnogih, da bodo oni lahko rešeni.',
    },
    11: {
        1: 'Bodite moji posnemovalci, celó kakor sem tudi jaz Kristusov.',
        2: 'Hvalim vas torej, bratje, da se me spominjate v vseh stvareh in se držite odredb, kakor sem vam jih izročil.',
        3: 'Toda želel bi, da veste, da je glava vsakemu možu Kristus; in glava ženski je mož; in glava Kristusu je Bog.',
        4: 'Vsak mož, ki moli ali prerokuje in ima svojo glavo pokrito, onečašča svojo glavo.',
        5: 'Toda vsaka ženska, ki moli ali prerokuje s svojo nepokrito glavo, onečašča svojo glavo; ker je to celó isto, kakor če bi bila ostrižena na kratko.',
        6: 'Kajti če se ženska ne pokriva, naj bo tudi ostrižena; toda če je za žensko sramotno, da bi bila ostrižena ali ostrižena na kratko, naj bo pokrita.',
        7: 'Kajti mož zares ne bi smel pokrivati svoje glave, ker je podoba in slava Boga; toda ženska je slava moškega.',
        8: 'Kajti moški ni iz ženske, temveč ženska iz moškega.',
        9: 'Niti ni bil moški ustvarjen zaradi ženske, temveč ženska zaradi moškega.',
        10: 'Zaradi tega razloga mora ženska na svoji glavi imeti oblast, zaradi angelov.',
        11: 'Pa vendar v Gospodu ni niti moškega brez ženske niti ženske brez moškega.',
        12: 'Kajti kakor je ženska iz moškega, točno tako je tudi moški po ženski; toda vse stvari od Boga.',
        13: 'Presodite v sebi; ali je primerno, da ženska nepokrita moli k Bogu?',
        14: 'Ali vas ne uči celó sama narava, če ima moški dolge lase, da je to njemu sramota?',
        15: 'Toda če ima ženska dolge lase, je njej to slava, kajti lasje so ji dani za pokrivalo.',
        16: 'Toda če je katerikoli človek videti prepirljiv, mi take navade nimamo niti Božje cerkve ne.',
        17: 'Torej s tem, kar vam navajam, vas ne hvalim, ker se ne shajate na boljše, temveč na slabše.',
        18: 'Kajti predvsem, ko se shajate v cerkvi, slišim, da so med vami nesoglasja; in deloma temu verjamem.',
        19: 'Kajti med vami morajo biti tudi krivoverci, da se med vami lahko razodenejo tisti, ki so preizkušeni.',
        20: 'Ko torej pridete skupaj na en kraj, to ni, da jeste Gospodovo večerjo.',
        21: 'Ker pri jedi vsakdo poprej vzame svojo lastno večerjo; in je eden lačen, drugi pa pijan.',
        22: 'Kaj? Mar nimate hiš, da bi v njih jedli in pili? Ali prezirate Božjo cerkev in sramotite te, ki nimajo? Kaj naj vam rečem? Naj vas hvalim v tem? Ne hvalim vas.',
        23: 'Kajti od Gospoda sem prejel to, kar sem vam tudi izročil: »Da je Gospod Jezus isto noč, v kateri je bil izdan, vzel kruh',
        24: 'in ko se je zahvalil, ga je razlomil in rekel: ›Vzemite, jejte. To je moje telo, ki je zlomljeno za vas. To delajte v moj spomin.‹',
        25: 'Na isti način je vzel tudi čašo, ko je srknil, rekoč: ›Ta čaša je nova zaveza v moji krvi. To delajte tako pogosto, kot to pijete, v moj spomin.‹«',
        26: 'Kajti tako pogosto, kot jeste ta kruh in pijete to čašo, razodevate Gospodovo smrt, dokler ne pride.',
        27: 'Zato kdorkoli bo nevredno jedel ta kruh in pil to Gospodovo čašo, bo kriv Gospodovega telesa in krvi.',
        28: 'Toda vsak človek naj izpraša samega sebe in naj tako jé od tega kruha in pije od te čaše.',
        29: 'Kajti kdor jé in pije nevredno, jé in pije obsodbo samemu sebi in ne razpoznava Gospodovega telesa.',
        30: 'Zaradi tega razloga so mnogi med vami slabotni in bolehni in mnogi spijo.',
        31: 'Kajti če bi sodili sami sebe, bi ne bili sojeni.',
        32: '§ Toda ko smo sojeni, smo okarani od Gospoda, da ne bi bili obsojeni s svetom.',
        33: 'Zatorej, moji bratje, kadar pridete skupaj, da jeste, počakajte drug na drugega.',
        34: 'In če je katerikoli človek lačen, naj jé doma, da se ne shajate v obsodbo. Ostalo pa bom uredil, ko pridem.',
    },
    12: {
        1: 'Torej glede duhovnih darov, bratje, vas ne bi hotel imeti nevedne.',
        2: 'Vi veste, da ste bili pogani, zapeljani k tem nemim malikom, celó kakor ste bili vodeni.',
        3: 'Zatorej vam dajem razumeti, da nihče, ki govori po Božjem Duhu, ne imenuje Jezusa preklet; in da noben človek ne more reči, da Jezus je Gospod, razen po Svetem Duhu.',
        4: 'Torej obstaja raznolikost darov, toda isti Duh.',
        5: 'In obstaja drugačnost služenj, toda isti Gospod.',
        6: 'In obstaja raznolikost del, toda to je isti Bog, ki dela vse v vseh.',
        7: 'Toda manifestacija Duha je dana vsakemu človeku, da s tem koristi.',
        8: 'Kajti enemu je po Duhu dana beseda modrosti; drugemu po istem Duhu beseda spoznanja;',
        9: 'drugemu vera po istem Duhu; še drugemu po istem Duhu darovi ozdravljanja;',
        10: 'drugemu delanje čudežev; drugemu prerokba; drugemu razpoznavanje duhov; drugemu številne vrste jezikov; drugemu razlaga jezikov.',
        11: 'Toda vse to počne ta en in točno isti Duh, ki vsakemu človeku razdeljuje posamično, kakor on hoče.',
        12: 'Kajti kakor je telo eno in ima mnogo udov in so vsi udi od tega enega telesa, čeprav mnogi, so eno telo; tako je tudi Kristus.',
        13: 'Kajti po enem Duhu smo vsi krščeni v eno telo, bodisi smo Judje ali pogani, bodisi smo vezani ali svobodni; vsi pa smo bili napojeni v enem Duhu.',
        14: 'Kajti telo ni en ud, temveč mnogo.',
        15: 'Če bo stopalo reklo: »Ker nisem roka, nisem od telesa;« ali potemtakem ni od telesa?',
        16: 'In če bo uho reklo: »Ker nisem oko, nisem od telesa;« ali potemtakem ni od telesa?',
        17: 'Če bi bilo celotno telo oko, kje bi bil sluh? Če bi bilo celotno sluh, kje bi bil vonj?',
        18: 'Toda sedaj je Bog vsakega od teh udov razporedil po telesu, kakor mu je ugajalo.',
        19: 'In če bi bili vsi en ud, kje bi bilo telo?',
        20: 'Vendar so sedaj oni številni udje, vendar samo eno telo.',
        21: 'In oko ne more reči roki: »Ne potrebujem te,« prav tako tudi ne glava stopalu: »Ne potrebujem te.«',
        22: 'Ne, potrebnih je veliko več teh telesnih udov, ki so videti slabotnejši.',
        23: 'In ti telesni udje, za katere mislimo, da so manj častitljivi, na te podelimo obilnejšo čast; in naši neprivlačni deli imajo obilnejšo ljubkost.',
        24: 'Kajti naši ljubki deli nimajo potrebe; toda Bog je pripravil skupaj telo in dal obilnejšo čast temu delu, ki trpi pomanjkanje,',
        25: 'da v telesu ne bi bilo razkola; temveč, da bi imeli udje enako skrb drug za drugega.',
        26: 'In če en ud trpi, vsi udje trpijo z njim; ali [če] je en ud spoštovan, se vsi udje veselijo z njim.',
        27: 'Torej vi ste Kristusovo telo in predvsem udje.',
        28: 'In Bog je postavil nekatere v cerkvi, najprej apostole, drugič preroke, tretjič učitelje, nató čudeže, potem darove ozdravljanj, pomoči, upravljanj, raznolikost jezikov.',
        29: 'So vsi apostoli? So vsi preroki? So vsi učitelji? So vsi delavci čudežev?',
        30: 'Imajo vsi darove ozdravljanja? Ali vsi govorijo z jeziki? Ali vsi razlagajo?',
        31: 'Toda iskreno hrepenite po najboljših darovih; in vendar vam pokažem še odličnejšo pot.',
    },
    13: {
        1: 'Čeprav govorim s človeškimi in angelskimi jeziki, pa nimam ljubezni, sem postal kakor brneč bron ali zveneča cimbala.',
        2: 'In čeprav imam dar preroštva in razumem vse skrivnosti in vsa spoznanja; in čeprav imam vso vero, tako da lahko premikam gore, pa nimam ljubezni, nisem nič.',
        3: 'In čeprav podelim vse svoje dobrine, da nahranim revne in čeprav izročim svoje telo, da bi izgorelo, nimam pa ljubezni, mi to nič ne koristi.',
        4: 'Ljubezen dolgo prenaša in je prijazna; ljubezen ni nevoščljiva; ljubezen sebe ne povzdiguje, ni napihnjena,',
        5: 'se ne ponaša nespodobno, ne išče svojega lastnega, ni lahko izzvana, ne misli zlega;',
        6: 'ne razveseljuje se v krivičnosti, temveč se razveseljuje v resnici;',
        7: 'prenese vse stvari, veruje vsem stvarem, upa [v] vse stvari, vzdrži vse stvari.',
        8: 'Ljubezen nikoli ne izneveri. Toda če bodo preroštva, bodo prenehala; če bodo jeziki, bodo prenehali; če bo spoznanje, bo to izginilo proč.',
        9: 'Kajti spoznavamo deloma in prerokujemo deloma.',
        10: 'Toda ko pride to, kar je popolno, takrat bo to, kar je deloma, odpravljeno.',
        11: 'Ko sem bil otrok, sem govoril kakor otrok, razumel kakor otrok, mislil kakor otrok. Toda ko sem postal mož, sem otročje stvari dal stran.',
        12: '§ Kajti sedaj vidimo skozi steklo, temno; toda takrat iz obličja v obličje; sedaj spoznavam deloma, toda takrat bom spoznal enako, kakor sem bil tudi spoznan.',
        13: 'In sedaj ostajajo vera, upanje, ljubezen, to troje; toda največja od teh je ljubezen.',
    },
    14: {
        1: 'Prizadevajte si za ljubezen in želite si duhovne darove, toda rajši, da boste lahko prerokovali.',
        2: '§ Kajti kdor govori v neznanem jeziku, ne govori ljudem, temveč Bogu, kajti noben človek ga ne razume, čeprav v duhu govori skrivnosti.',
        3: 'Toda kdor prerokuje, govori ljudem v izgrajevanje, spodbudo in tolažbo.',
        4: 'Kdor govori v neznanem jeziku, izgrajuje sebe; toda kdor prerokuje, izgrajuje cerkev.',
        5: 'Hočem, da vi vsi govorite z jeziki, toda rajši, da prerokujete. Kajti večji je, kdor prerokuje, kakor kdor govori z jeziki, razen če razlaga, da lahko cerkev prejme izgrajevanje.',
        6: 'Torej bratje, če pridem k vam, govoreč z jeziki, kaj vam bom koristil, razen če vam ne bom govoril ali po razodetju ali po spoznanju ali po prerokovanju ali po nauku?',
        7: 'In celó stvari brez življenja dajejo zvok, bodisi piščal ali harfa [in] razen če ne dajo razlike v zvokih, kako bo razpoznano kaj je piskano ali harfano?',
        8: 'Kajti če trobenta da nerazločen zvok, kdo se bo pripravil za boj?',
        9: 'Tako tudi vi, razen če ne boste z jezikom izrekli lahko razumljivih besed, kako se bo izvedelo, kar je rečeno? Kajti v zrak boste govorili.',
        10: 'Obstaja, kakor se vé, tako veliko vrst glasov in nobeden od njih ni brez pomena.',
        11: 'Zatorej, če ne vem pomena glasu, bom temu, ki govori, tujec in kdor govori, bo zame tujec.',
        12: 'Tako si tudi vi, ker ste vneti za duhovne darove, prizadevajte, da se boste lahko izkazali pri izgrajevanju cerkve.',
        13: 'Zatorej naj tisti, ki govori v neznanem jeziku, moli, da bo lahko razlagal.',
        14: 'Kajti če molim v neznanem jeziku, moli moj duh, toda moje razumevanje je brez sadu.',
        15: 'Kaj je to torej? Molil bom z duhom in molil bom tudi z razumom; pel bom z duhom in pel bom tudi z razumom.',
        16: 'Sicer, ko boš blagoslavljal z duhom, kako bo, kdor zavzema prostor nepoučenega, ob tvojem zahvaljevanju rekel: »Amen,« glede na to, da ne razume, kar praviš?',
        17: 'Kajti ti resnično daješ prisrčno zahvalo, toda drug ni izgrajen.',
        18: 'Zahvaljujem se svojemu Bogu, bolj kakor vi vsi govorim z jeziki.',
        19: 'Vendar v cerkvi raje spregovorim pet besed s svojim razumom, da bi lahko s svojim glasom poučil tudi druge, kakor deset tisoč besed v neznanem jeziku.',
        20: 'Bratje, ne bodite otroci v razumevanju. Čeprav ste v zlobnosti otroci, vendar v razumevanju bodite možje.',
        21: 'V postavi je pisano: ›Z ljudmi drugih jezikov in drugih ustnic bom govoril tem ljudem; in vendar me kljub vsemu temu ne bodo slišali,‹ govori Gospod.',
        22: 'Zato so jeziki za znamenje, ne tem, ki verujejo, temveč tem, ki ne verujejo. Toda prerokovanje ne služi tem, ki ne verujejo, temveč tem, ki verujejo.',
        23: 'Če bi torej celotna cerkev prišla skupaj na en kraj in bi vsi govorili z jeziki in vstopijo tisti, ki so nepoučeni ali neverniki, ali ne bodo rekli, da ste blazni?',
        24: 'Toda če vsi prerokujejo in vstopi nekdo, ki ne veruje ali nekdo nepoučen, je prepričan od vseh, je sojen od vseh.',
        25: 'In tako so razodete skrivnosti njegovega srca; in tako pade na svoj obraz in bo oboževal Boga ter naznanil, da je Bog resnično v vas.',
        26: 'Kako je to potem, bratje? Ko pridete skupaj, ima vsak izmed vas psalm, ima nauk, ima jezik, ima razodetje, ima razlago. Naj bodo vse stvari storjene k izgrajevanju.',
        27: '§ Če katerikoli človek govori v neznanem jeziku, naj bosta po dva ali največ po trije in to po vrsti; eden pa naj razlaga.',
        28: 'Toda če tam ni razlagalca, naj v cerkvi molči; govori pa naj sebi in Bogu.',
        29: 'Naj spregovorijo dva ali trije preroki, drugi pa naj sodijo.',
        30: 'Če je katerakoli stvar razodeta drugemu, ki sedi v bližini, naj prvi molči.',
        31: 'Kajti vsi lahko prerokujete eden za drugim, da se vsi lahko učijo in ste vsi lahko potolaženi.',
        32: 'In duhovi prerokov so podrejeni prerokom.',
        33: 'Kajti Bog ni povzročitelj zmešnjave, temveč miru, kakor v vseh cerkvah svetih.',
        34: 'Naj vaše ženske v cerkvah molčijo, kajti ni jim dovoljeno govoriti; temveč jim je naročeno biti pod poslušnostjo, kakor pravi tudi postava.',
        35: 'In če se hočejo karkoli naučiti, naj doma vprašajo svoje soproge, kajti za ženske je sramotno, da v cerkvi govorijo.',
        36: 'Kaj? Ali je Božja beseda prišla od vas? Je dospela samo k vam?',
        37: 'Če katerikoli človek misli o sebi, da je prerok ali duhoven, naj prizna, da so besede, ki vam jih pišem, zapovedi od Boga.',
        38: 'Toda če je katerikoli človek neveden, naj bo neveden.',
        39: 'Zato bratje, hrepenite da prerokujete in ne prepovejte govoriti z jeziki.',
        40: 'Naj bodo vse stvari storjene spodobno in urejeno.',
    },
    15: {
        1: 'Poleg tega, bratje, vam razglašam evangelij, ki sem vam ga oznanil, ki ste ga tudi sprejeli in v katerem stojite;',
        2: 'po katerem ste tudi rešeni, če obdržite v spominu, kar sem vam oznanil, razen če ste zaman verovali.',
        3: 'Kajti predvsem sem vam izročil to, kar sem tudi sam prejel, kako je ta Kristus umrl za naše grehe, glede na pisma;',
        4: 'in da je bil pokopan in da je bil tretji dan obujen, glede na pisma;',
        5: 'in da ga je videl Kefa, nató dvanajsteri.',
        6: 'Potem ga je hkrati videlo več kot petsto bratov; od katerih jih je večji del ostal do sedaj, toda nekateri so zaspali.',
        7: 'Nató ga je videl Jakob, potem vsi apostoli.',
        8: 'In zadnji od vseh sem ga videl tudi jaz, kakor nekdo rojen izven pravšnjega časa.',
        9: 'Kajti jaz sem najmanjši izmed apostolov, ki nisem primeren, da sem imenovan apostol, ker sem preganjal Božjo cerkev.',
        10: 'Toda po Božji milosti sem, kar sem, in njegova milost, ki mi je bila podeljena, ni bila zaman; temveč sem se trudil bolj obilno kakor vsi oni. Vendar ne jaz, temveč Božja milost, ki je bila z menoj.',
        11: 'Torej bodisi sem bil jaz ali oni, takó oznanjamo in takó ste verovali.',
        12: 'Torej če se oznanja Kristusa, ki je obujen od mrtvih, kako nekateri izmed vas pravite, da ni vstajenja mrtvih?',
        13: 'Toda če ni bilo vstajenja mrtvih, potem Kristus ni obujen.',
        14: 'Če pa Kristus ni bil obujen, potem je naše oznanjevanje prazno in je tudi vaša vera prazna.',
        15: 'Da, spoznani smo [za] krive Božje priče, ker smo pričevali o Bogu, ki je obudil Kristusa; ki ga ni obudil, če je tako, da mrtvi ne vstajajo.',
        16: 'Kajti če mrtvi ne vstajajo, potem Kristus ni obujen.',
        17: 'Če pa Kristus ni bil obujen, je vaša vera prazna; še vedno ste v svojih grehih.',
        18: 'Tedaj so propadli tudi tisti, ki so zaspali v Kristusu.',
        19: 'Če imamo samo v tem življenju upanje v Kristusa, smo od vseh ljudi najbolj bedni.',
        20: 'Toda sedaj je Kristus obujen od mrtvih in postal prvenec teh, ki so zaspali.',
        21: 'Kajti odkar je po človeku prišla smrt, je po človeku prišlo tudi vstajenje mrtvih.',
        22: 'Kajti kakor v Adamu vsi umrejo, bodo točno tako v Kristusu vsi oživljeni.',
        23: 'Toda vsak po svojem lastnem redu; prvenec Kristus, zatem tisti, ki so Kristusovi, ob njegovem prihodu.',
        24: 'Potem pride konec, ko bo kraljestvo izročil Bogu, celó Očetu; ko bo odstranil vsako vladavino in vsako oblast ter moč.',
        25: 'Kajti on mora kraljevati, dokler ne položi vseh sovražnikov pod njegova stopala.',
        26: 'Zadnji sovražnik, ki bo uničen, je smrt.',
        27: 'Kajti vse stvari je položil pod njegova stopala. Toda ko pravi, vse stvari so položene pod njega, je očitno, da je tisti, ki je vse stvari položil pod njega, izvzet.',
        28: 'In ko mu bodo vse stvari podjarmljene, potem bo tudi Sin sebe podvrgel njemu, ki je vse stvari položil pod njega, da bo lahko Bog vse v vsem.',
        29: 'Sicer kaj bodo storili tisti, ki se krščujejo za mrtve, če mrtvi sploh niso obujeni? Zakaj so bili potem krščeni za mrtve?',
        30: 'In čemu mi vsako uro stojimo v nevarnosti?',
        31: 'Pri svojem veselju, ki ga imam v Kristusu Jezusu, našem Gospodu, izjavljam: »Vsak dan umiram.«',
        32: 'Če sem se v Efezu po človeško boril z zvermi, kaj mi koristi, če mrtvi niso obujeni? Jejmo in pijmo, kajti jutri umremo.',
        33: '§ Ne bodite zavedeni. Zli pogovori pokvarijo dobre manire.',
        34: 'Zbudite se k pravičnosti in ne grešite, kajti nekateri nimajo Božjega spoznanja. To vam govorim v vašo sramoto.',
        35: 'Toda nekateri ljudje bodo rekli: »Kako so mrtvi obujeni? In s kakšnim telesom pridejo?«',
        36: 'Ti bedak, to kar ti seješ, ne oživi, razen če ne umre.',
        37: 'In to, kar ti seješ, ne seješ tega telesa, ki bo, temveč golo zrno, to je lahko pšenica ali neko drugo zrno;',
        38: 'toda Bog mu daje telo, kakor mu ugaja in vsakemu semenu svoje lastno telo.',
        39: 'Ni vse meso isto meso, ampak je ena vrsta mesa od ljudi, drugo meso od živali, drugo od rib in drugo od ptic.',
        40: 'Tam so tudi nebesna telesa in zemeljska telesa; toda slava nebesnih je ena, slava zemeljskih pa je druga.',
        41: 'Ena je slava sonca, druga slava lune in druga slava zvezd, kajti ena zvezda se od druge zvezde razlikuje po slavi.',
        42: 'Tako je tudi vstajenje mrtvih. Sejano je v trohljivosti, obujeno je v netrohljivosti.',
        43: 'Sejano je v nečast, dvignjeno je v slavo. Sejano je v slabosti, dvignjeno je v moči.',
        44: '§ Sejano je v naravno telo, dvignjeno je duhovno telo. Obstaja naravno telo in obstaja duhovno telo.',
        45: 'In tako je pisano: ›Prvi človek Adam je postal živa duša;‹ zadnji Adam je postal oživljajoč duh.',
        46: 'Vendar ni bilo najprej to, kar je duhovno, temveč to, kar je naravno, in potem to, kar je duhovno.',
        47: 'Prvi človek je iz tal, zemeljski; drugi človek je Gospod iz nebes.',
        48: 'Kakršen je zemeljski, takšni so tudi tisti, ki so zemeljski; in kakršen je nebeški, takšni so tudi tisti, ki so nebeški.',
        49: 'In kakor smo nosili zemeljsko podobo, bomo nosili tudi nebeško podobo.',
        50: 'Torej povem to, bratje, da meso in kri ne moreta podedovati Božjega kraljestva; niti trohnenje ne podeduje netrohnenja.',
        51: 'Glejte, pokažem vam skrivnost: ›Ne bomo vsi zaspali, toda vsi bomo spremenjeni,',
        52: 'v trenutku, kot bi trenil z očesom, ob zadnji trobenti, kajti trobenta bo zadonela in mrtvi bodo vstali netrohneči in mi bomo spremenjeni.‹',
        53: 'Kajti ta trohljivost si mora nadeti netrohljivost in to umrljivo si mora nadeti nesmrtnost.',
        54: 'Torej ko si bo ta trohljivost nadela netrohljivost in si bo to umrljivo nadelo nesmrtnost, tedaj se bo izpolnila beseda, ki je zapisana: ›Smrt je požrta v zmagi.',
        55: '§ Oh smrt, kje je tvoje želo? Oh grob, kje je tvoja zmaga?‹',
        56: 'Želo smrti je greh, moč greha pa je postava.',
        57: 'Toda zahvaljen bodi Bog, ki nam daje zmago po našem Gospodu Jezusu Kristusu.',
        58: 'Torej, moji ljubljeni bratje, bodite neomajni, nepremakljivi, vedno obilni v Gospodovem delu, ker veste, da vaš trud v Gospodu ni zaman.',
    },
    16: {
        1: 'Torej glede nabirke za svete, kakor sem dal naročilo cerkvam v Galatiji, točno tako storite.',
        2: 'Na prvi dan tedna naj vsak izmed vas položi poleg sebe v shrambo, kakor ga je Bog osrečil, da ne bo zbiranj, ko pridem.',
        3: 'In ko pridem, katerekoli boste z vašimi pismi priporočili, te bom poslal, da prinesejo vašo velikodušnost v Jeruzalem.',
        4: 'Če pa bo primerno, da grem tudi jaz, bodo šli z menoj.',
        5: 'Torej, ko bom šel skozi Makedonijo, bom prišel k vam; kajti pojdem skozi Makedonijo.',
        6: '§ In lahko bo, da bom ostal, da in prezimil z vami, da me boste lahko spremili na moje potovanje, kamorkoli pojdem.',
        7: 'Kajti ne bom vas torej videl mimogrede; temveč zaupam, da ostanem nekaj časa z vami, če Gospod dovoli.',
        8: 'Toda v Efezu bom ostal do binkošti.',
        9: 'Kajti velika in uspešna vrata so se mi odprla in tam je mnogo nasprotnikov.',
        10: 'Torej če pride Timótej, glejte, da bo lahko z vami brez strahu, kajti opravlja Gospodovo delo, kakor ga opravljam tudi jaz.',
        11: 'Naj ga torej nihče ne prezira, temveč ga spremite v miru, da bo lahko prišel k meni, ker ga pričakujem z brati.',
        12: 'Glede našega brata Apola, sem ga silno prosil, da pride z brati k vam, toda njegova volja sploh ni bila, da pride ob tem času; toda prišel bo, ko bo imel primeren čas.',
        13: 'Čujte, trdno stojte v veri, obnašajte se kakor možje, bodite močni.',
        14: 'Naj bodo vse vaše stvari narejene z ljubeznijo.',
        15: 'Rotim vas, bratje (vi poznate Stefanájevo hišo, da je ta prvenec Ahaje in da so sebe posvetili službi svetim),',
        16: 'da se takšnim podredite in vsakemu, ki pomaga z nami in se trudi.',
        17: '§ Vesel sem Stefanájevega, Fortunatovega in Aháikovega prihoda, kajti preskrbeli so to, kar je manjkalo na vaši strani.',
        18: 'Kajti okrepčali so mojega in vašega duha; zatorej jim priznajte, da so takšni.',
        19: 'Pozdravljajo vas cerkve iz Azije. V Gospodu vas zelo pozdravljata Ákvila in Priska, s cerkvijo, ki je v njuni hiši.',
        20: 'Pozdravljajo vas vsi bratje. Drug drugega pozdravite s svetim poljubom.',
        21: 'Pozdrav od mene, Pavla, z mojo lastno roko.',
        22: 'Če kateri človek nima rad Gospoda Jezusa Kristusa, naj bo Anathema Maranatha.',
        23: '§ Milost našega Gospoda Jezusa Kristusa bodi z vami.',
        24: 'Moja ljubezen bodi z vami vsemi v Kristusu Jezusu. Amen. [Prva poslanica Korinčanom je bila napisana iz Filipov po Stefanáju in Fortunatu in Aháiku in Timóteju.]',
    },
}
